'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { Navbar } from '@/components/layout/Navbar';
import { useDesignStore } from '@/lib/store';

// Minimal Scene3D - no store usage
function MinimalScene3D() {
  return (
    <div className="w-full h-full bg-gradient-to-b from-gray-900 to-gray-800 flex items-center justify-center">
      <div className="text-white/60 text-sm">3D Scene Placeholder</div>
    </div>
  );
}

export default function StudioPage() {
  const router = useRouter();
  const { currentDesign } = useDesignStore();
  const [isClient, setIsClient] = useState(false);

  useEffect(() => {
    setIsClient(true);
    console.log('[DEBUG] StudioPage - currentDesign:', currentDesign);
    if (!currentDesign) {
      console.log('[DEBUG] StudioPage - No currentDesign, redirecting to templates');
      router.push('/templates');
    }
  }, [currentDesign, router]);

  // Prevent hydration mismatch by rendering loading state on server
  if (!isClient) {
    return (
      <div className="h-screen flex flex-col bg-[#F7F7F5]">
        <Navbar />
        <div className="flex-1 flex items-center justify-center">
          <div className="text-[#5A5A5F]">Loading Studio...</div>
        </div>
      </div>
    );
  }

  if (!currentDesign) {
    console.log('[DEBUG] StudioPage - Rendering null (no currentDesign)');
    return null;
  }
  
  console.log('[DEBUG] StudioPage - Rendering with currentDesign:', currentDesign.id, currentDesign.name);

  return (
    <div className="h-screen flex flex-col bg-[#F7F7F5]">
      <Navbar />
      
      {/* Simple Header */}
      <div className="pt-16 lg:pt-20 bg-white border-b border-[#E5E5E8] shrink-0 p-4">
        <h1 className="text-lg font-semibold text-[#111111]">{currentDesign.name}</h1>
        <p className="text-xs text-[#8C8C92]">{currentDesign.objects.length} objects</p>
      </div>

      {/* Just the placeholder scene - no panels, no store-using children */}
      <div className="flex-1 relative bg-[#F0EFE9]">
        <MinimalScene3D />
      </div>
    </div>
  );
}
